$occ['children']??0)?'Çocuk: '.((int)$occ['children']):'')?:'—'];$ruleJson=htmlspecialchars((string)json_encode($rv,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),ENT_QUOTES,'UTF-8');?><p><b><?=htmlspecialchars($r['name'])?></b> · <?=htmlspecialchars($r['property_name'])?> · <?=htmlspecialchars($r['rule_type'])?> <?=htmlspecialchars($r['value'])?> · öncelik <?=htmlspecialchars($r['priority'])?> · <?=htmlspecialchars($r['status'])?><?php if($expired):?> <em style="color:#b26a00">(satış penceresi bitti)</em><?php endif;?><?php if(($r['status']??'active')!=='active'||$expired):?> <a class="rule-detail-link" title="<?=htmlspecialchars($rtt['rule_inspect'])?>" href="#" data-rule="<?=$ruleJson?>" style="color:#b26a00;text-decoration:none;border-bottom:1px dotted #b26a00;cursor:pointer">İncele →</a><?php else:?> <a class="rule-detail-link" title="<?=htmlspecialchars($rtt['rule_view'])?>" href="#" data-rule="<?=$ruleJson?>" style="color:#4a6d8c;text-decoration:none;border-bottom:1px dotted #4a6d8c;cursor:pointer">Gör →</a><?php endif;?></p><?php endforeach;?></section><div class="rule-modal-backdrop" id="rule-modal" hidden><div class="rule-modal" role="dialog" aria-modal="true" aria-labelledby="rule-modal-title"><button type="button" class="rule-modal-close" id="rule-modal-close" aria-label="Kapat">✕</button><h3 id="rule-modal-title"></h3><dl class="rule-modal-grid"><div><dt>Tip</dt><dd id="rule-f-type"></dd></div><div><dt>Değer</dt><dd id="rule-f-value"></dd></div><div><dt>Ürün</dt><dd id="rule-f-property"></dd></div><div><dt>Fiyat planı</dt><dd id="rule-f-rate"></dd></div><div><dt>Durum</dt><dd id="rule-f-status"></dd></div><div><dt>Öncelik</dt><dd id="rule-f-priority"></dd></div><div><dt>Birleşebilir</dt><dd id="rule-f-stackable"></dd></div><div><dt>Promosyon kodu</dt><dd id="rule-f-promo"></dd></div><div><dt>Satış penceresi</dt><dd id="rule-f-booking"></dd></div><div><dt>Konaklama</dt><dd id="rule-f-stay"></dd></div><div><dt>Min. erken rezervasyon</dt><dd id="rule-f-min-advance"></dd></div><div><dt>Pazarlar</dt><dd id="rule-f-markets"></dd></div><div><dt>Uyruklar</dt><dd id="rule-f-nationalities"></dd></div><div><dt>Kanallar</dt><dd id="rule-f-channels"></dd></div><div><dt>Doluluk</dt><dd id="rule-f-occupancy"></dd></div></dl></div></div><script>(function(){var m=document.getElementById('rule-modal');if(!m)return;function openRule(a){try{var r=JSON.parse(a.getAttribute('data-rule'));}catch(e){return;}document.getElementById('rule-modal-title').textContent=r.name;var map={'rule-f-type':'type','rule-f-value':'value','rule-f-property':'property','rule-f-rate':'rate','rule-f-status':'status','rule-f-priority':'priority','rule-f-stackable':'stackable','rule-f-promo':'promo','rule-f-booking':'booking','rule-f-stay':'stay','rule-f-min-advance':'min_advance','rule-f-markets':'markets','rule-f-nationalities':'nationalities','rule-f-channels':'channels','rule-f-occupancy':'occupancy'};for(var id in map){var el=document.getElementById(id);if(el)el.textContent=(r[map[id]]==null||r[map[id]]==='')?'—':String(r[map[id]]);}m.hidden=false;document.body.style.overflow='hidden';}function closeRule(){m.hidden=true;document.body.style.overflow='';}document.addEventListener('click',function(e){var t=e.target;if(t&&t.classList&&t.classList.contains('rule-detail-link')){e.preventDefault();openRule(t);return;}if(t===m||t.classList.contains('rule-modal-backdrop')||t.id==='rule-modal-close')closeRule();});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&!m.hidden)closeRule();});})();</script><?php supply_end();
